Translate("frFR", "moonglade", {
	title = "Reflet-de-Lune",
	aliases = { "la clairière" },
	sections = {
		{
			title = "Résumé",
			text = [=[Reflet-de-Lune est un vallon caché dans les montagnes du nord de {link:kalimdor}Kalimdor{/link}, entre {link:felwood}Gangrebois{/link} et {link:winterspring}Berceau-de-l'Hiver{/link}. Un lac paisible s'étend en son cœur, entouré d'herbe argentée et d'arbres anciens, et sur ses rives se dresse le village de {link:nighthaven}Havrenuit{/link}. C'est la terre sacrée du {link:cenarion-circle}Cercle cénarien{/link}, l'ordre des druides, et le siège du gardien {link:keeper-remulos}Remulos{/link}, fils de {link:cenarius}Cenarius{/link}. Aucune armée ne la tient. {link:night-elves}Elfes de la nuit{/link} et taurens parcourent ses sentiers en amis, et ses gardiens ne tolèrent aucune violence à l'intérieur de ses frontières.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte l'année où les druides firent pour la première fois de Reflet-de-Lune leur refuge. Ses noms disent quelque chose de son passé. Le lac porte le nom d'Elune, la déesse lunaire des {link:night-elves}elfes de la nuit{/link}. Les refuges de l'est portent le nom de {link:malfurion-stormrage}Malfurion Stormrage{/link}, le premier druide, dont les disciples apprirent à dormir de longs âges dans le {link:emerald-dream}Rêve d'émeraude{/link}. Les druides disent que ceux qui hibernent à Reflet-de-Lune dorment sous la garde du gardien. Ce ne fut jamais une cité ni une forteresse, seulement un lieu d'enseignement et de repos.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La clairière est en paix, mais le Cercle qui y demeure ne l'est pas. {link:malfurion-stormrage}Malfurion{/link} dort et n'est pas revenu. À {link:darnassus}Darnassus{/link}, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} dirige les druides des elfes de la nuit, et lui et le gardien {link:keeper-remulos}Remulos{/link} en sont venus à se méfier l'un de l'autre. Chacun soupçonne l'autre de fourberie, tandis que l'étrange corruption de {link:teldrassil}Teldrassil{/link} continue sans être guérie. Reflet-de-Lune s'est plutôt tourné vers l'extérieur. Ses druides ont accueilli les {link:tauren}taurens{/link}, et à travers eux la {link:horde}Horde{/link}. Ses envoyés cherchent l'aide de tout peuple prêt à la donner : contre le poison en {link:darkshore}Sombrivage{/link}, contre la Gangreliane d'Eldre'Thalas, et contre un mal ancien qui s'éveille en {link:silithus}Silithus{/link}. Depuis peu, des druides {link:skyborne}shen'dorei{/link}, venus d'une île lointaine dans le ciel, sont arrivés à {link:nighthaven}Havrenuit{/link}, et un esprit de leur patrie est venu à leur rencontre.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les druides du {link:cenarion-circle}Cercle cénarien{/link}.{/b} {link:night-elves}Elfes de la nuit{/link} et taurens qui enseignent, étudient et dorment dans la clairière, menés par le gardien {link:keeper-remulos}Remulos{/link} et son majordome, {link:rabine-saturna}Rabine Saturna{/link}.
• {b}Les gardiens de Reflet-de-Lune.{/b} Des sentinelles du Cercle qui maintiennent la paix de la clairière et gardent son sanctuaire.
• {b}Les grands esprits.{/b} Des esprits anciens de la nature, qui enseignent aux jeunes druides les formes de leur espèce.
• {b}Les morts sans repos.{/b} Dans le {link:stormrage-barrow-dens}Refuge des saisons de Malfurion{/link}, les esprits des druides de la Griffe tombés errent dans la colère.
• {b}Les Grumegueules.{/b} Les furbolgs des {link:timbermaw-hold}Grumegueules{/link} gardent les tunnels qui sont la seule route vers la clairière, et ils n'accueillent pas tous les voyageurs.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}L'âge des Anciens.{/b} Les druides apprirent leur art de {link:cenarius}Cenarius{/link} pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, et le conservèrent durant dix mille ans, passés pour la plupart dans le sommeil.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Quand la {link:burning-legion}Légion ardente{/link} revint, les druides s'éveillèrent pour combattre. Cenarius tomba en {link:ashenvale}Orneval{/link}, et lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, {link:nordrassil}Nordrassil{/link} livra sa puissance pour détruire {link:archimonde}Archimonde{/link}.
• {b}Le Cercle ouvert.{/b} Après la guerre, le Cercle accueillit des druides taurens, {link:hamuul-runetotem}Hamuul Runetotem{/link} le premier. Reflet-de-Lune devint la terre commune des deux peuples.]=],
		},
		{
			title = "Légendes de la clairière",
			text = [=[• Les druides parlent d'Omen, un grand loup de la guerre des Anciens que la magie démoniaque retourna contre ses alliés. Abattu à Reflet-de-Lune, il dort dans le lac {link:lake-elune-ara}Elune'ara{/link} et s'éveille une fois par an, lors de la fête lunaire.
• Au sud de la clairière, au-delà de {link:felwood}Gangrebois{/link} et de {link:winterspring}Berceau-de-l'Hiver{/link}, s'élèvent les hauteurs de {link:mount-hyjal}Mount Hyjal{/link}, où {link:nordrassil}Nordrassil{/link} se dresse toujours. Les refuges des druides de la Griffe s'enfoncent aussi profondément sous cette montagne, et les plus profonds d'entre eux se nomment {link:the-barrow-deeps}The Barrow Deeps{/link}.
• {link:umber}Umber{/link}, l'archiviste de {link:nighthaven}Havrenuit{/link}, avertit chaque visiteur de ne jamais faire attendre {link:rabine-saturna}Rabine Saturna{/link}. Ceux qui le font, dit-il, risquent de se retrouver couverts de miel.]=],
		},
	},
})

Translate("frFR", "nighthaven", {
	title = "Havrenuit",
	sections = {
		{
			title = "Résumé",
			text = [=[Havrenuit est le seul village de {link:moonglade}Reflet-de-Lune{/link}, bâti le long des rives du lac {link:lake-elune-ara}Elune'ara{/link}. Ses maisons sont élevées dans l'ancien style des elfes de la nuit, et à côté d'elles se dressent les tentes des druides taurens qui ont rejoint le Cercle. {link:rabine-saturna}Rabine Saturna{/link} tient les affaires du village pour le gardien {link:keeper-remulos}Remulos{/link}. {link:dendrite-starblaze}Dendrite Starblaze{/link} et {link:loganaar}Loganaar{/link} instruisent les jeunes druides qui viennent ici, et l'archiviste {link:umber}Umber{/link} erre parmi ses étagères. Des montures du Cercle portent les druides jusqu'à {link:darnassus}Darnassus{/link} et {link:thunder-bluff}Thunder Bluff{/link}, tandis que des hippogriffes et des coursiers du vent attendent aux abords de la clairière. Havrenuit est isolé et vit replié sur lui-même. Ce n'est qu'à la fête lunaire qu'il ouvre les bras à tous les peuples du monde.]=],
		},
	},
})

Translate("frFR", "shrine-of-remulos", {
	title = "Sanctuaire de Remulos",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Sanctuaire de Remulos se dresse au nord-ouest de {link:moonglade}Reflet-de-Lune{/link}, parmi de vieux arbres au bord du lac. C'est là que le gardien lui-même monte le plus souvent sa garde. Le sanctuaire rend hommage à l'œuvre du {link:cenarion-circle}Cercle cénarien{/link}, la préservation de la nature et de l'équilibre, et la gardienne {link:tajarri}Tajarri{/link} le sert. Les jeunes druides qui réussissent l'épreuve du Lac rapportent une babiole des eaux profondes et l'offrent au sanctuaire en signe de respect. Non loin au nord, le {link:great-bear-spirit}Grand esprit de l'ours{/link} a élu domicile.]=],
		},
	},
})

Translate("frFR", "lake-elune-ara", {
	title = "Lac Elune'ara",
	aliases = { "Elune'ara" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le lac Elune'ara emplit le cœur de {link:moonglade}Reflet-de-Lune{/link}. Il porte le nom d'Elune, et ses eaux claires et profondes reflètent la lune au-dessus de la clairière. {link:nighthaven}Havrenuit{/link} se dresse sur ses rives, et des ponts le franchissent là où la terre se resserre. Le lac fait partie de l'enseignement du Cercle. Les jeunes druides plongent dans ses profondeurs à la recherche de babioles du sanctuaire, qui s'estompent vite une fois sorties à l'air. Le lac garde aussi un secret plus ancien. On dit que le loup déchu Omen dort dans sa vase, béni par Elune et incapable de mourir.]=],
		},
	},
})

Translate("frFR", "stormrage-barrow-dens", {
	title = "Refuge des saisons de Malfurion",
	aliases = { "Refuge des saisons" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge des saisons de Malfurion s'étend au sud-est de {link:moonglade}Reflet-de-Lune{/link}, derrière une grande porte à flanc de colline. Il porte le nom de {link:malfurion-stormrage}Malfurion Stormrage{/link}, et c'est le lieu de repos des druides. Tous ceux qui y reposent ne le font pas en paix. Des esprits enragés des druides de la Griffe errent dans ses salles, et ils se jettent sur quiconque y entre. Le {link:great-cat-spirit}Grand esprit du félin{/link}, qui demeure non loin, garde trois reliques de sa faveur dans le refuge. Une statue à l'entrée prête un manteau d'ombre à ceux qui doivent se glisser devant les esprits pour les réclamer.]=],
		},
	},
})

Translate("frFR", "keeper-remulos", {
	title = "Gardien Remulos",
	subtitle = "Gardien de Reflet-de-Lune",
	found = "Le Sanctuaire de Remulos, au nord-ouest de Havrenuit",
	hint = [=[Cherchez le fils de Cenarius au sanctuaire qui porte son nom.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Remulos" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le gardien Remulos est un fils du demi-dieu {link:cenarius}Cenarius{/link} et le gardien de {link:moonglade}Reflet-de-Lune{/link}. Comme son père, c'est un être de la nature sauvage, autant forêt que chair. Il veille sur la clairière sacrée et sur les druides qui y dorment, et il guide le {link:cenarion-circle}Cercle cénarien{/link} dans son œuvre : la préservation de la nature et de l'équilibre.]=],
		},
		{
			title = "Importance",
			text = [=[Avec {link:malfurion-stormrage}Malfurion Stormrage{/link} perdu dans le {link:emerald-dream}Rêve d'émeraude{/link}, les druides ont deux centres, et deux chefs. À {link:darnassus}Darnassus{/link}, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} gouverne depuis les branches du nouvel Arbre-Monde. À {link:moonglade}Reflet-de-Lune{/link}, Remulos garde la terre plus ancienne. Les deux ne se font plus confiance. Remulos a choisi d'ouvrir la clairière à tous ceux qui servent le monde vivant, taurens et elfes de la nuit, {link:horde}Horde{/link} et {link:alliance}Alliance{/link} tout ensemble. C'est depuis sa clairière, et non depuis la cité de l'archidruide, que le Cercle appelle désormais des champions mortels contre les dangers de {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Un fils de Cenarius",
			text = [=[Les gardiens du bosquet sont les fils de {link:cenarius}Cenarius{/link}, et Remulos est l'un d'eux. Son frère Zaetar était le premier fils. Il y a longtemps, Zaetar rechercha la princesse Theradras, une grande puissance de la terre élémentaire, et elle lui donna les premiers centaures. Ses propres enfants se retournèrent contre lui et le tuèrent, et Theradras emporta sa dépouille dans les cavernes de {red:maraudon}Maraudon{/red}. Remulos crut son frère perdu à jamais pour l'arrogance et la rage. Puis, pendant la {link:third-war}Troisième Guerre{/link}, son père tomba sous les coups des orcs en {link:ashenvale}Orneval{/link}. Remulos a beaucoup perdu à cause des races mortelles. Il ne leur a pas fermé {link:moonglade}la clairière{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il garde {link:moonglade}Reflet-de-Lune{/link} et les druides qui y hibernent.
• Il guide le {link:cenarion-circle}Cercle cénarien{/link} depuis le {link:shrine-of-remulos}Sanctuaire de Remulos{/link}.
• Par la voix de son majordome, {link:rabine-saturna}Rabine Saturna{/link}, il appelle les peuples du monde à aider le Cercle en {link:silithus}Silithus{/link} et dans les ruines d'Eldre'Thalas.
• Il accueille les taurens, et la {link:horde}Horde{/link} à travers eux, dans la clairière.]=],
		},
		{
			title = "Non consigné",
			text = [=[On a peu écrit sur Remulos avant l'âge présent : quel rôle il joua dans les guerres du monde ancien, ou quand il vint pour la première fois garder {link:moonglade}Reflet-de-Lune{/link}. Cette entrée ne consigne que ce que révèlent ses paroles et sa charge.]=],
		},
	},
	chapters = {
		{
			title = "Le Cercle divisé",
			hint = "Répondez à l'appel du Cercle à Reflet-de-Lune.",
			text = [=[Quand le Cercle demanda de l'aide dans le lointain ouest, l'appel passa par {link:thunder-bluff}Thunder Bluff{/link} et par {link:darnassus}Darnassus{/link}. À Thunder Bluff, il fut entendu avec joie. À Darnassus, l'archidruide refusa de l'entendre lui-même. Il avertit que {link:moonglade}Reflet-de-Lune{/link} ne répandait que de la propagande, et qu'il avait seul mené son peuple hors des ténèbres. Son propre second admit que l'archidruide et le gardien se soupçonnaient mutuellement de fourberie. On promit à ceux qui vinrent malgré tout à la clairière qu'ils étaient parmi des amis, et qu'aucun mal venu de Darnassus ne les atteindrait là.]=],
		},
		{
			title = "La graine de Zaetar",
			hint = "Apportez au gardien un présent de l'esprit de son frère.",
			text = [=[Au fond de Maraudon, là où Theradras gardait sa dépouille, l'esprit de Zaetar s'attardait. Il ne voulait pas quitter ses enfants, même après tout ce qu'ils avaient fait. Il envoya à la place la première graine qui avait poussé de la vie que sa dépouille avait nourrie, avec un message pour son frère : son esprit demeurait là. Quand la graine atteignit {link:moonglade}Reflet-de-Lune{/link}, Remulos comprit. Son frère n'était pas perdu. Il s'était rendu à la nature, comme c'était son devoir, et avait enfin trouvé la paix. Le gardien sentit que la graine compterait un jour pour le peuple de cette terre déchirée par la guerre.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, envoyé à son majordome]=],
		},
		{
			text = [=[{link:rabine-saturna}Rabine Saturna{/link}, envoyé depuis {link:darnassus}Darnassus{/link}]=],
		},
		{ text = "The New Frontier" },
		{ text = "Seed of Life" },
		{ text = "Trial of the Lake, à son sanctuaire" },
	},
	bonds = {
		{ id = "cenarius", name = "Cenarius", note = "son père" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "le premier druide, qui dort" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "son rival à Darnassus" },
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "son majordome" },
		{ id = "tajarri", name = "Tajarri", note = "gardienne de son sanctuaire" },
		{ id = "keeper-marandis", name = "Gardien Marandis", note = "cherche la dépouille de son frère" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "amène les taurens au Cercle" },
	},
})

Translate("frFR", "rabine-saturna", {
	title = "Rabine Saturna",
	subtitle = "Majordome du gardien Remulos",
	found = "Havrenuit, au bord du lac",
	hint = [=[Cherchez le majordome du gardien dans le village de Havrenuit.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Rabine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rabine Saturna est le majordome du gardien {link:keeper-remulos}Remulos{/link}. Il parle au nom du gardien à ceux qui viennent à {link:moonglade}Reflet-de-Lune{/link}, et il les accueille au nom de tous ceux qui demeurent dans la clairière sacrée. Il est patient et courtois, et il n'oublie jamais une dette. L'archiviste {link:umber}Umber{/link} l'appelle la mère poule de {link:nighthaven}Havrenuit{/link}, et pas toujours avec bienveillance.]=],
		},
		{
			title = "Importance",
			text = [=[Rabine est la main que {link:moonglade}Reflet-de-Lune{/link} tend au monde. Par lui, le Cercle demande à des étrangers de tous les peuples de faire ce que ses druides ne peuvent faire seuls. Il croit que la préservation d'{link:azeroth}Azeroth{/link} est une cause partagée par la {link:horde}Horde{/link} et l'{link:alliance}Alliance{/link}, quelles que soient leurs querelles, et quoi qu'en dise l'archidruide de {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il accueille dans {link:moonglade}la clairière{/link} les envoyés de {link:thunder-bluff}Thunder Bluff{/link} et de {link:darnassus}Darnassus{/link}, et leur promet protection.
• Il envoie des agents vers l'ouest en {link:silithus}Silithus{/link}, où une guerre ancienne fut jadis livrée entre les elfes de la nuit et une puissance étrangère.
• Il envoie des chercheurs dans les ruines du village de {link:southwind-village}Sudevent{/link} pour y trouver un Reliquaire de pureté.
• Il cherche à mettre sous scellés un éclat de la Gangreliane d'Eldre'Thalas.]=],
		},
	},
	chapters = {
		{
			title = "Les terres désolées",
			hint = [=[Portez la lettre du majordome dans les terres désolées au-delà d'Un'Goro.]=],
			text = [=[À l'ouest du {link:un-goro-crater}Cratère d'Un'Goro{/link} s'étend un désert dont peu d'elfes de la nuit se souviennent. Il y a longtemps, leur peuple y combattit un ennemi terrible et l'enferma. Rabine craint que quelque chose ne cherche maintenant à l'éveiller. Il envoya une lettre à {link:layo-starstrike}Layo Starstrike{/link}, l'agent du Cercle au {link:valor-s-rest}Repos des vaillants{/link}, le lieu de sépulture des morts des terres désolées. Ce que Layo y trouva commença à lui donner raison. Avec le temps, Layo renvoya un étrange objet scellé dans de la chitine, destiné à l'archiviste de {link:nighthaven}Havrenuit{/link}.]=],
		},
		{
			title = "La Gangreliane",
			hint = [=[Apportez au majordome un éclat de la liane corrompue, mis sous scellés.]=],
			text = [=[Dans les salles orientales d'Eldre'Thalas, en {link:feralas}Féralas{/link}, un {link:satyrs}satyre{/link} nommé Alzzin le Modeleur sauvage s'était emparé du Fruit de fertilité et l'avait corrompu en Gangreliane. Aucun réceptacle ordinaire ne pouvait contenir une chose si immonde. Rabine se souvint d'un Reliquaire de pureté laissé dans le village de {link:southwind-village}Sudevent{/link}, en {link:silithus}Silithus{/link}, bien des années auparavant. Quand le reliquaire fut retrouvé et l'éclat scellé à l'intérieur, il nomma son porteur héros du Cercle. La guerre, avertit-il, était loin d'être finie.]=],
		},
	},
	mentions = {
		{ text = "Rabine Saturna" },
		{ text = "Rabine Saturna" },
		{ text = "Wasteland" },
		{ text = "Uncovering Past Secrets" },
		{ text = "A Reliquary of Purity" },
		{ text = "Shards of the Felvine" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Gardien Remulos", note = "son maître" },
		{ id = "umber", name = "Umber", note = "l'archiviste du Cercle" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "lui envoie les taurens" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "lui envoie les elfes de la nuit" },
	},
})

Translate("frFR", "dendrite-starblaze", {
	title = "Dendrite Starblaze",
	subtitle = "Maître des jeunes druides",
	found = "Havrenuit, au nord du village",
	hint = [=[Cherchez le druide de Havrenuit qui enseigne aux jeunes leurs premières formes.]=],
	allegiance = "Cercle cénarien",
	aliases = { "Dendrite" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dendrite Starblaze est un druide du {link:cenarion-circle}Cercle cénarien{/link} qui enseigne à {link:nighthaven}Havrenuit{/link}. Presque tous les jeunes druides des elfes de la nuit et des taurens passent entre ses mains. Il accueille chacun d'eux d'une prière discrète au père {link:cenarius}Cenarius{/link} et d'un petit geste invisible qui le remplit de puissance. Puis il les envoie apprendre de la nature elle-même.]=],
		},
		{
			title = "Importance",
			text = [=[Dendrite garde la plus ancienne tradition des druides : les formes de la nature doivent se mériter, et non simplement s'accorder. Il envoie ses élèves auprès des grands esprits, dans le lac et parmi les bêtes malades du monde, et il les juge à ce qu'ils rapportent. Aujourd'hui, des druides {link:skyborne}shen'dorei{/link} viennent aussi à lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes druides auprès du {link:great-bear-spirit}Grand esprit de l'ours{/link} pour apprendre la nature de l'ours.
• Il impose l'épreuve du Lac et l'épreuve de l'Otarie à ceux qui veulent prendre la forme aquatique.
• Il envoya de jeunes druides en {link:darkshore}Sombrivage{/link} quand {link:auberdine}Auberdine{/link} demanda à {link:moonglade}Reflet-de-Lune{/link} de l'aide pour des cerfs empoisonnés.
• Il envoie des élèves auprès du {link:great-cat-spirit}Grand esprit du félin{/link}, et les {link:skyborne}shen'dorei{/link} auprès d'un esprit de leur propre patrie.]=],
		},
	},
	chapters = {
		{
			title = "La voie de la Griffe",
			hint = [=[Allez trouver le Grand esprit de l'ours sur la parole de Dendrite.]=],
			text = [=[La première leçon de Dendrite est toujours l'ours. Il envoie chaque élève auprès du {link:great-bear-spirit}Grand esprit de l'ours{/link}, au nord-ouest de {link:moonglade}la clairière{/link}, et il attend. À leur retour, il cherche un changement dans leurs yeux : une sagesse nouvelle, une force qui n'a pas encore trouvé sa direction.]=],
		},
		{
			title = "Du poison dans l'eau",
			hint = "Aidez les cerfs de Sombrivage au nom du Cercle.",
			text = [=[{link:auberdine}Auberdine{/link} avait demandé l'aide de {link:moonglade}Reflet-de-Lune{/link}, et Dendrite en fit une leçon. Ce n'était pas un exercice, avertit-il. L'eau des {link:cliffspring-falls}Chutes de la Bondissante{/link} empoisonnait les cerfs de {link:darkshore}Sombrivage{/link}, et l'élève devait les soigner à la main, comme le ferait un profane, avant d'apprendre à le faire d'un mot. Auberdine renvoya ses remerciements. Dendrite y ajouta un avertissement de son cru : certains, à {link:darnassus}Darnassus{/link}, choisissent de ne pas voir la corruption qui se répand sur la terre.]=],
		},
		{
			title = "Le grand félin",
			hint = "Gagnez la bénédiction du Grand esprit du félin.",
			text = [=[Ces temps-ci, Dendrite envoie aussi ses élèves vers le sud, auprès du {link:great-cat-spirit}Grand esprit du félin{/link}, à côté du {link:stormrage-barrow-dens}Refuge des saisons de Malfurion{/link}. Pour les {link:skyborne}shen'dorei{/link}, il a un autre guide : un esprit félin porté par les vents, venu de leur propre île, qui est venu à {link:moonglade}la clairière{/link} et les a demandés par leur nom.]=],
		},
	},
	mentions = {
		{ text = "Moonglade" },
		{ text = "Moonglade" },
		{ text = "Great Bear Spirit" },
		{ text = "A Lesson to Learn" },
		{ text = "Trial of the Sea Lion" },
		{ text = "Lessons Anew" },
		{ text = "Power over Poison" },
		{ text = "The Great Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-bear-spirit", name = "Grand esprit de l'ours", note = "le premier maître de ses élèves" },
		{ id = "great-cat-spirit", name = "Grand esprit du félin", note = "met ses élèves à l'épreuve" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "enseigne à ses élèves shen'dorei" },
		{ id = "tajarri", name = "Tajarri", note = "juge l'épreuve du Lac" },
		{ id = "alanndarian-nightsong", name = "Alanndarian Nightsong", note = "a demandé de l'aide à Reflet-de-Lune" },
		{ id = "mathrengyl-bearwalker", name = "Mathrengyl Bearwalker", note = "lui envoie des élèves" },
	},
})

Translate("frFR", "umber", {
	title = "Umber",
	subtitle = "Archiviste du Cercle cénarien",
	found = "Parmi les étagères de Havrenuit",
	hint = [=[Cherchez l'archiviste qui erre parmi les étagères de Havrenuit.]=],
	allegiance = "Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Umber est l'archiviste du {link:cenarion-circle}Cercle cénarien{/link}. Il est brillant, distrait et un peu toqué, et il a sauvé des tomes en plus mauvais état que la plupart des érudits n'oseraient en ouvrir. Il marmonne tout seul en fouillant ses étagères à la recherche de papiers égarés. Il a entendu les rumeurs chuchotées d'horreurs dans le désert. Il n'a aucune affection pour les insectes, quels qu'ils soient, et il est bien content de rester avec ses livres.]=],
		},
		{
			title = "Importance",
			text = [=[Umber ouvrit la première fenêtre sur le passé de {link:silithus}Silithus{/link}. Un morceau de chitine envoyé du désert se révéla contenir un journal, écrit dans une forme très ancienne de la langue des elfes de la nuit.]=],
		},
	},
	mentions = {
		{ text = "Umber, Archivist" },
		{ text = "Uncovering Past Secrets" },
		{ text = "Under the Chitin Was..." },
	},
	bonds = {
		{ id = "rabine-saturna", name = "Rabine Saturna", note = "la mère poule, selon ses mots" },
	},
})

Translate("frFR", "loganaar", {
	title = "Loganaar",
	subtitle = "Maître des druides de Havrenuit",
	found = "Havrenuit",
	hint = [=[Cherchez le druide qui forme les membres du Cercle à Havrenuit.]=],
	allegiance = "Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Loganaar enseigne les arts du druide à {link:nighthaven}Havrenuit{/link}. Contrairement aux maîtres de {link:darnassus}Darnassus{/link} et de {link:thunder-bluff}Thunder Bluff{/link}, il ne sert aucune cité. Il forme tout druide du Cercle qui vient à {link:moonglade}la clairière{/link}, {link:night-elves}elfe de la nuit{/link} ou {link:tauren}tauren{/link}, et il ne demande rien de leurs cités ni de leurs querelles. Dans un Cercle divisé entre Reflet-de-Lune et Darnassus, ses leçons n'appartiennent qu'à la clairière.]=],
		},
		{
			title = "Importance",
			text = [=[Loganaar est souvent celui qui entend l'appel quand quelqu'un, au loin, demande l'aide d'un druide. Quand un chasseur nommé {link:torwa-pathfinder}Torwa Pathfinder{/link} fit savoir depuis le {link:un-goro-crater}Cratère d'Un'Goro{/link} que seul un druide pouvait l'aider, c'est Loganaar qui transmit le message.]=],
		},
	},
	mentions = {
		{ text = "{link:torwa-pathfinder}Torwa Pathfinder{/link}" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "enseigne dans le même village" },
	},
})

Translate("frFR", "tajarri", {
	title = "Tajarri",
	subtitle = "Gardienne du Sanctuaire de Remulos",
	found = "Le Sanctuaire de Remulos",
	hint = [=[Parlez à la gardienne qui veille sur le sanctuaire du gardien.]=],
	allegiance = "Cercle cénarien · Gardiens de Reflet-de-Lune",
	sections = {
		{
			title = "Résumé",
			text = [=[Tajarri est l'une des gardiennes les plus fiables de {link:moonglade}Reflet-de-Lune{/link}. Elle garde le {link:shrine-of-remulos}Sanctuaire de Remulos{/link}, et elle tient cela pour un privilège. Elle veille sur les jeunes druides qui accourent du lac, des babioles qui s'estompent entre les mains, et elle les presse quand le temps vient à manquer. D'autres druides fouillent peut-être les mêmes eaux, et la babiole n'attend pas. Elle connaît aussi la seconde épreuve, et elle envoie ceux qui cherchent les moitiés du Pendentif de l'otarie demander aux gens de la clairière où elles se trouvent.]=],
		},
		{
			title = "Importance",
			text = [=[Tajarri est le juge de l'épreuve du Lac. Par elle, chaque jeune druide apprend que le sanctuaire honore le plus ancien devoir du Cercle, la garde de l'équilibre de la nature.]=],
		},
	},
	mentions = {
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Lake" },
		{ text = "Trial of the Sea Lion" },
	},
	bonds = {
		{ id = "keeper-remulos", name = "Gardien Remulos", note = "le maître de son sanctuaire" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "lui envoie les jeunes" },
	},
})

Translate("frFR", "great-bear-spirit", {
	title = "Grand esprit de l'ours",
	subtitle = "Maître de la Griffe",
	found = "Le nord-ouest de Reflet-de-Lune",
	hint = [=[Cherchez l'esprit sage qui demeure au nord-ouest de la clairière.]=],
	allegiance = "Les esprits de la nature · Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Grand esprit de l'ours demeure au nord-ouest de {link:moonglade}Reflet-de-Lune{/link}. C'est un être sage et noble, et il a été pour tous les druides le premier maître dans la nature de l'ours. Les druides de {link:darnassus}Darnassus{/link} disent qu'il fait partie du monde depuis que le monde tourne parmi les étoiles.]=],
		},
		{
			title = "Importance",
			text = [=[Chaque jeune druide de la Griffe vient ici au début de la voie. De l'esprit, ils emportent sagesse et force. Leurs maîtres comptent sur sa puissance pour alimenter leur dessein. La rencontre est toujours la même, disent les druides : un peu déroutante, et très intense.]=],
		},
	},
	mentions = {
		{ text = "Great Bear Spirit" },
		{ text = "Great Bear Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "lui envoie des élèves" },
		{ id = "urs-endris", name = "Urs'endris", note = "l'esprit de l'ours de Zephras" },
	},
})

Translate("frFR", "great-cat-spirit", {
	title = "Grand esprit du félin",
	subtitle = "Maître de l'ombre silencieuse",
	found = [=[Le sud de Reflet-de-Lune, à l'ouest du Refuge des saisons de Malfurion]=],
	hint = [=[Cherchez l'esprit du félin près des refuges, au sud de la clairière.]=],
	allegiance = "Les esprits de la nature · Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Grand esprit du félin demeure au sud de {link:moonglade}Reflet-de-Lune{/link}, près du {link:stormrage-barrow-dens}Refuge des saisons de Malfurion{/link}. Il enseigne aux jeunes druides la nature du félin : la ruse, la discrétion, et la férocité quand il ne reste plus aucune issue. Les mots seuls ne le satisfont pas. Ceux qui viennent à lui doivent montrer ce qu'ils sont, et non le dire.]=],
		},
		{
			title = "Importance",
			text = [=[Ceux qui veulent prendre sa forme doivent d'abord reprendre trois reliques de sa faveur dans le refuge, en passant devant les esprits enragés des druides de la Griffe. Une statue à l'entrée du refuge leur prête la discrétion. Ce n'est que lorsque les trois reliques lui sont rendues qu'il donne sa bénédiction, et qu'il souhaite à ses élèves des ombres pour les cacher et des proies qui tombent aisément sous leurs griffes.]=],
		},
	},
	mentions = {
		{ text = "The Great Cat Spirit" },
		{ text = "Blessings of the Great Cat Spirit" },
	},
	bonds = {
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "lui envoie des élèves" },
		{ id = "avatar-of-saeyleenan", name = "Avatar de Saeyleenan", note = "un esprit félin de Zephras" },
	},
})

Translate("frFR", "avatar-of-saeyleenan", {
	title = "Avatar de Saeyleenan",
	subtitle = "Le grand esprit félin porté par les vents",
	found = "Le sud de Reflet-de-Lune, au sud des ponts jumeaux",
	hint = [=[Cherchez l'esprit porté par les vents, venu d'une île lointaine au sud de la clairière.]=],
	allegiance = "Les esprits de Zephras",
	aliases = { "Saeyleenan" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Avatar de Saeyleenan est un esprit félin porté par les vents, venu de {link:zephras-isle}Zephras Isle{/link}, la patrie des {link:skyborne}shen'dorei{/link}. Il est apparu depuis peu à {link:moonglade}Reflet-de-Lune{/link} et a demandé aux druides de {link:nighthaven}Havrenuit{/link} de lui envoyer les jeunes druides de son peuple. Il leur enseigne la forme féline de Zephras, qui diffère un peu de celle que l'on connaît sur {link:azeroth}Azeroth{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[L'Avatar est un signe que les esprits de {link:zephras-isle}Zephras{/link} n'ont pas oublié leurs enfants. Il leur impose la même épreuve que le {link:great-cat-spirit}Grand esprit du félin{/link}, dans les refuges à l'est de sa demeure. À ceux qui réussissent, il donne sa bénédiction et souhaite que les vents guident leurs pas. Il n'a plus grand-chose à leur enseigner ici, dit-il, et il espère les revoir sur Zephras.]=],
		},
	},
	mentions = {
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "The Great Windborne Cat Spirit" },
		{ text = "Blessings of the Great Windborne Cat Spirit" },
	},
	bonds = {
		{ id = "great-cat-spirit", name = "Grand esprit du félin", note = "son pendant dans la clairière" },
		{ id = "urs-endris", name = "Urs'endris", note = "un grand esprit de la même île" },
		{ id = "dendrite-starblaze", name = "Dendrite Starblaze", note = "guide ses élèves" },
	},
})
